from datetime import datetime
import difflib

def detect_duplicate(movement, others):
    def amount_matches(m1, m2):
        a1 = m1.get('creditAmount', 0) or m1.get('debitAmount', 0)
        a2 = m2.get('creditAmount', 0) or m2.get('debitAmount', 0)
        return a1 == a2 and a1 != 0

    def reference_or_description_match(m1, m2):
        if m1['reference'] == m2['reference']:
            return True
        if m1['description'] == m2['description']:
            return True
        similarity = difflib.SequenceMatcher(None, m1['description'], m2['description']).ratio()
        return similarity >= 0.8

    def date_in_window(m1_date, m2_date):
        diff = (datetime.fromisoformat(m1_date) - datetime.fromisoformat(m2_date)).days
        return abs(diff) <= 7

    for other in others:
        if amount_matches(movement, other) and reference_or_description_match(movement, other) and date_in_window(movement['transactionDate'], other['transactionDate']):
            if movement['reference'] == other['reference']:
                reason = "Duplicado por referencia y monto"
                confidence = 1.0
            elif movement['description'] == other['description']:
                reason = "Duplicado por descripción y monto"
                confidence = 1.0
            else:
                similarity = difflib.SequenceMatcher(None, movement['description'], other['description']).ratio()
                reason = "Duplicado por descripción similar y monto"
                confidence = similarity
            return {
                "isDuplicate": True,
                "originalMovementId": other['id'],
                "confidence": confidence,
                "reason": reason
            }
    return None
