def application_decision(amount, open_invoices, balance):
    if not open_invoices:
        if balance and balance.get('amount', 0) > 0:
            return {
                'type': 'balance_forward',
                'details': 'Saldo a favor por balance previo'
            }
        return {
            'type': 'advance',
            'details': 'Anticipo'
        }

    exact_invoice = next(
        (inv for inv in open_invoices if inv['balance'] == amount),
        None
    )
    if exact_invoice:
        return {
            'type': 'full',
            'invoiceId': exact_invoice['id'],
            'details': f"Factura {exact_invoice['id']} abonada totalmente"
        }

    oldest = min(open_invoices, key=lambda i: i['dueDate'])
    return {
        'type': 'partial',
        'invoiceId': oldest['id'],
        'details': f"Abono parcial a factura {oldest['id']}"
    }
